"use strict";
/**
 * Bundler: concatenates src/**.js into a single Tampermonkey-installable
 * userscript.
 *
 * There is no third-party bundler involved, on purpose - a userscript has to
 * ship as one plain, readable file, and the transform needed here is small
 * and fully reversible:
 *
 *   - `import { ... } from "..."` lines are deleted. After concatenation
 *     every module shares one function scope, so the bindings the imports
 *     referred to are simply in scope.
 *   - A leading `export ` on a declaration is deleted, leaving the plain
 *     `function`/`const`/`let`/`class` declaration behind.
 *   - Each module's body is indented by two spaces and wrapped in the
 *     original IIFE + "use strict".
 *   - Every comment is removed and collected for dist/comments.md, so the
 *     shipped script is plain code. The ==UserScript== header, the context
 *     table and the per-module section banners are not comments "from a
 *     module" and stay put - see lib/comments.js.
 *
 * Nothing else about the source is rewritten, so the bundled output stays
 * diffable against the compiled modules.
 */
const fs = require("fs");
const path = require("path");
const { listJsFiles } = require("./lib/wiring");
const { findComments, removeComments, verifyStrip } = require("./lib/comments");

const ROOT = path.join(__dirname, "..");
const SRC = path.join(ROOT, "src");
const META = path.join(ROOT, "meta");

/** Fails the build if modules.json and the files on disk disagree. */
function verifyManifestMatchesDisk(order) {
  const errors = [];
  const onDisk = listJsFiles(SRC)
    .map((f) => path.relative(SRC, f).split(path.sep).join("/"))
    .filter((f) => f !== "package.json");
  const listed = new Set(order);

  for (const f of order) {
    if (!fs.existsSync(path.join(SRC, f))) {
      errors.push(`modules.json lists "${f}", but src/${f} does not exist`);
    }
  }
  for (const f of onDisk) {
    if (!listed.has(f)) {
      errors.push(`src/${f} exists but is not listed in build/modules.json - it would be silently left out of the bundle`);
    }
  }
  return errors;
}

const IMPORT_RE = /^[ \t]*import\s*\{[\s\S]*?\}\s*from\s*["'][^"']+["'];?[ \t]*\r?\n/gm;
const SIDE_EFFECT_IMPORT_RE = /^[ \t]*import\s*["'][^"']+["'];?[ \t]*\r?\n/gm;
const EXPORT_PREFIX_RE = /^export[ \t]+(?=(?:async[ \t]+)?function|const|let|class)/gm;
const EXPORT_LIST_RE = /^[ \t]*export\s*\{[\s\S]*?\};?[ \t]*\r?\n/gm;

/** Turns one ES module's source into bundle-ready, indented plain script. */
function transformModule(src) {
  let out = src.replace(IMPORT_RE, "").replace(SIDE_EFFECT_IMPORT_RE, "");
  out = out.replace(EXPORT_LIST_RE, "");
  out = out.replace(EXPORT_PREFIX_RE, "");
  out = out.replace(/^\n+/, "").replace(/\s+$/, "");
  return out
    .split("\n")
    .map((line) => (line.trim() === "" ? "" : "  " + line))
    .join("\n");
}

/** Builds the auto-generated table of contents from the module order. */
function buildTableOfContents(order) {
  const width = Math.max(...order.map((f) => f.length));
  const lines = [
    "/* === osu! Local Favorites ===",
    " *",
    " * This file is GENERATED by build/build.js from the modules under src/.",
    " * Do not edit it directly - edit the module and rebuild, or your change",
    " * will be overwritten on the next build.",
    " *",
    " * Bundled modules, in concatenation order:",
    " *",
  ];
  order.forEach((f, i) => {
    const n = String(i + 1).padStart(2, " ");
    lines.push(` *   ${n}. ${f.padEnd(width)}  (src/${f})`);
  });
  lines.push(" */");
  return lines.join("\n");
}

/**
 * Assembles the whole file line by line, so that the line each removed comment
 * used to be attached to is known in the final numbering. `strip` false
 * produces the unstripped reference the losslessness check compares against.
 */
function assemble(order, header, toc, { strip }) {
  const lines = [];
  const sections = [];
  const errors = [];
  const push = (text) => {
    for (const line of String(text).split("\n")) lines.push(line);
  };

  push(header);
  push("");
  push(toc);
  push("(() => {");
  push('  "use strict";');
  push("");

  for (const file of order) {
    const raw = fs.readFileSync(path.join(SRC, file), "utf8");
    const body = transformModule(raw);
    push(`  // ━━━━━━━━━━ src/${file} ━━━━━━━━━━`);
    push("");

    const startLine = lines.length + 1; // bodyStart, 1-based
    if (!strip) {
      push(body);
      sections.push({ file, comments: [], bodyStart: startLine, bodyLines: body.split("\n").length });
      continue;
    }

    const { lines: bodyLines, anchors } = removeComments(body);
    const base = lines.length; // lines emitted so far = index of the next one
    for (const line of bodyLines) lines.push(line);

    // The comments are scanned from the *module file*, not from its compiled
    // body, so each entry can also report where it lives in src/. The two
    // scans see the same comments in the same order (the transform only drops
    // import lines and re-indents); a mismatch means that assumption broke and
    // comments.md would attribute text to the wrong line, so it fails here.
    const sourceComments = findComments(raw);
    if (sourceComments.length !== anchors.length) {
      errors.push(
        `src/${file}: ${sourceComments.length} comments in the module but ${anchors.length} in its compiled body - ` +
          `the bundler transform changed the comments (comments.md would misreport them)`,
      );
    }

    const lastBodyLine = Math.max(bodyLines.length, 1);
    const comments = anchors.map((relative, index) => {
      const source = sourceComments[index] || { text: "", line: 0, column: 0 };
      return {
        line: base + Math.min(Math.max(relative, 1), lastBodyLine),
        // Text comes from the module file, not from the compiled body, so the
        // markdown shows the comment as it is written in src/.
        text: source.text,
        sourceLine: source.line,
        column: source.column,
      };
    });

    sections.push({ file, comments, bodyStart: startLine, bodyLines: bodyLines.length });
  }

  push("");
  push("})();");
  return { code: lines.join("\n") + "\n", sections, totalLines: lines.length, errors };
}

function bundle() {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, "modules.json"), "utf8"));
  const order = manifest.order;

  const manifestErrors = verifyManifestMatchesDisk(order);
  if (manifestErrors.length) return { errors: manifestErrors, code: null };

  const header = fs.readFileSync(path.join(META, "userscript-header.txt"), "utf8").replace(/\s+$/, "");
  const toc = buildTableOfContents(order);

  const stripped = assemble(order, header, toc, { strip: true });
  if (stripped.errors.length) return { errors: stripped.errors, code: null };

  // Safety net for the comment scanner and the line mapping: fail the build
  // rather than ship a userscript that lost code or kept comments.
  const full = assemble(order, header, toc, { strip: false });
  const allComments = stripped.sections.flatMap((s) => s.comments);
  const problems = verifyStrip(full.code, stripped.code, allComments);
  if (problems.length) {
    return {
      errors: [
        "comment stripping did not produce a clean, code-identical bundle (build/lib/comments.js):",
        ...problems.map((p) => `  ${p}`),
      ],
      code: null,
    };
  }

  return {
    errors: [],
    code: stripped.code,
    comments: {
      sections: stripped.sections,
      total: stripped.sections.reduce((n, s) => n + s.comments.length, 0),
    },
  };
}

module.exports = { bundle, transformModule, verifyManifestMatchesDisk };
